        __half2 g_hi = *reinterpret_cast<__half2*>(&g_vec.y);
        __half2 u_lo = *reinterpret_cast<__half2*>(&u_vec.x);
        __half2 u_hi = *reinterpret_cast<__half2*>(&u_vec.y);

