        r_lo.y = (g_lo_f.y / (1.0f + expf(-g_lo_f.y))) * u_lo_f.y;
        r_hi.x = (g_hi_f.x / (1.0f + expf(-g_hi_f.x))) * u_hi_f.x;
        r_hi.y = (g_hi_f.y / (1.0f + expf(-g_hi_f.y))) * u_hi_f.y;

