        *reinterpret_cast<__half2*>(&result.x) = __float22half2_rn(r_lo);
        *reinterpret_cast<__half2*>(&result.y) = __float22half2_rn(r_hi);
        *reinterpret_cast<int2*>(gate + base) = result;
    }

